package ro.reflex.uvstudio;

import android.content.Context;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * 128x64 screen previews for the official overlay apps.
 *
 * The previews are published by the web client (js/app-screens.js, generated by
 * the firmware repository's app_screenshot.py). They are bundled here as a
 * plain "id base64" list, loaded once, so the catalog can show the same picture
 * without a network round trip.
 */
final class AppScreens {

    private static Map<String, String> cache;

    private AppScreens() { }

    static synchronized String get(Context context, String appId) {
        if (cache == null) cache = load(context);
        return cache.get(appId);
    }

    private static Map<String, String> load(Context context) {
        Map<String, String> map = new HashMap<>();
        try (InputStream in = context.getAssets().open("app-screens.txt");
             BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                int split = line.indexOf(' ');
                if (split <= 0 || split + 1 >= line.length()) continue;
                map.put(line.substring(0, split).trim(), line.substring(split + 1).trim());
            }
        } catch (Exception ignored) {
            /* no previews available: the catalog just shows text */
        }
        return map;
    }

    /** "AF-Scope.app" -> "afscope", the same key the web client uses. */
    static String idFor(String fileName) {
        if (fileName == null) return "";
        String base = fileName.replaceAll("(?i)\\.app$", "");
        return base.replaceAll("[^A-Za-z0-9]", "").toLowerCase(Locale.US);
    }
}
